CREATE PROCEDURE "DP_MULTIPLE_FORECAST_AUTO" (IN TBL_NAME NVARCHAR(100), IN CONTROLTBL_NAME NVARCHAR(100),OUT RESULT TABLE (GROUPID VARCHAR (100), TIMESTAMP INT, VALUE DOUBLE)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER   AS  BEGIN     DECLARE MULTIPLEFORECAST_CONTROLTBL TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "INTARGS" INT, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR(100));     DECLARE MULTIPLEFORECAST_OUTPARAMETER0 TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE MULTIPLEFORECAST_RESULT0 TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE MULTIPLEFORECAST_OUTPARAMETER1 TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE MULTIPLEFORECAST_RESULT1 TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE TEMP_MULTIPLEFORECAST_OUTPARAMETER TABLE ("GROUPID" VARCHAR (100), "NAME" VARCHAR(100), "VALUE" VARCHAR(100));     DECLARE TEMP_MULTIPLEFORECAST_RESULT TABLE ("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE, "DIFFERENCE" DOUBLE);     DECLARE FORECASTSLR_CONTROL TABLE ("NAME" VARCHAR (50), "INTARGS" INTEGER, "DOUBLEARGS" DOUBLE, "STRINGARGS" VARCHAR (100));     DECLARE FORECASTSLR_OUTPARAMETER TABLE ("NAME" VARCHAR (50), "VALUE" DOUBLE);     DECLARE FORECASTSLR_RESULT TABLE ("TIMESTAMP" INTEGER, "VALUE" DOUBLE);     DECLARE DATA_TABLE TABLE("GROUPID" VARCHAR (100), "TIMESTAMP" INT, "VALUE" DOUBLE);     DECLARE LR_DATA_TABLE TABLE("TIMESTAMP" INT, "Y" DOUBLE);     DECLARE ROWCNT INT;     DECLARE DIFF INT;     DECLARE ROWINDEX INT;     DECLARE GROUPCNT INT;     DECLARE NEGATIVE_VALUE_CNT INT;     DECLARE GROUPID VARCHAR (100);     DECLARE MAX_GROUP_VALUE DOUBLE;     DECLARE MAX_GROUP_FORECAST_VALUE DOUBLE;     DECLARE FORECAST_MODEL_NAME VARCHAR(100);     DECLARE LR_FORECAST_NUMBER VARCHAR(100);          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#SOURCEDATAHD73Y4GFKV093JDU';     IF ROWCNT>0 THEN     DROP TABLE #SOURCEDATAHD73Y4GFKV093JDU;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #SOURCEDATAHD73Y4GFKV093JDU LIKE PAL_MULTIPLEFORECASTSMOOTHING_DATA_T;     EXECUTE IMMEDIATE 'INSERT INTO #SOURCEDATAHD73Y4GFKV093JDU SELECT * FROM '||:TBL_NAME;     DATA_TABLE=SELECT * FROM #SOURCEDATAHD73Y4GFKV093JDU;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#FORECNTRSHUD93RF';     IF ROWCNT>0 THEN     DROP TABLE #FORECNTRSHUD93RF;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #FORECNTRSHUD93RF LIKE PAL_MULTIPLEFORECASTCONTROL_T;     EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF SELECT * FROM '||:CONTROLTBL_NAME;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPPALFORECASTSLRCONTROL';     IF ROWCNT>0 THEN     DROP TABLE #TEMPPALFORECASTSLRCONTROL;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPPALFORECASTSLRCONTROL LIKE PAL_FORECASTSLR_CONTROL_T;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPGROUPID';     IF ROWCNT>0 THEN         DROP TABLE #TEMPGROUPID;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPGROUPID ("GROUPID" VARCHAR (100), "MAXVALUE" DOUBLE);     INSERT INTO #TEMPGROUPID SELECT GROUPID, MAX("VALUE") AS MAXVALUE FROM :DATA_TABLE GROUP BY GROUPID;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPUTRESULT';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPUTRESULT;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPUTRESULT LIKE PAL_MULTIPLEFORECAST_T;          SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMPOUTPARAMETER';     IF ROWCNT>0 THEN         DROP TABLE #TEMPOUTPARAMETER;     END IF;     CREATE LOCAL TEMPORARY COLUMN TABLE #TEMPOUTPARAMETER LIKE MULTIPLEFORECAST_OUTPARAMETER_T;          SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF VALUES (''' || :GROUPID || ''',''SEASONAL'',0, NULL, NULL)';         EXECUTE IMMEDIATE 'INSERT INTO #FORECNTRSHUD93RF VALUES (''' || :GROUPID || ''',''SEASONAL'',1, NULL, NULL)';     END FOR;          MULTIPLEFORECAST_CONTROLTBL=SELECT * FROM #FORECNTRSHUD93RF WHERE NAME<>'SEASONAL' UNION ALL SELECT * FROM #FORECNTRSHUD93RF WHERE NAME='SEASONAL'AND INTARGS=0;      CALL PALMULTIPLEFORECASTSMOOTHING_PROC( :DATA_TABLE, :MULTIPLEFORECAST_CONTROLTBL, :MULTIPLEFORECAST_OUTPARAMETER0, :MULTIPLEFORECAST_RESULT0) ;      MULTIPLEFORECAST_CONTROLTBL=SELECT * FROM #FORECNTRSHUD93RF WHERE NAME<>'SEASONAL' UNION ALL SELECT * FROM #FORECNTRSHUD93RF WHERE NAME='SEASONAL'AND INTARGS=1;     CALL PALMULTIPLEFORECASTSMOOTHING_PROC( :DATA_TABLE, :MULTIPLEFORECAST_CONTROLTBL, :MULTIPLEFORECAST_OUTPARAMETER1, :MULTIPLEFORECAST_RESULT1) ;      SELECT COUNT(*) INTO ROWCNT FROM #TEMPGROUPID;     FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          SELECT COUNT(*) INTO GROUPCNT FROM :DATA_TABLE WHERE GROUPID=:GROUPID;         SELECT (out0.VALUE-out1.VALUE) INTO DIFF FROM :MULTIPLEFORECAST_OUTPARAMETER0 out0 JOIN :MULTIPLEFORECAST_OUTPARAMETER1 out1 ON out0.NAME=out1.NAME          WHERE out0.NAME='MSE' AND out0.GROUPID =:GROUPID AND out1.GROUPID =:GROUPID;         IF DIFF<=0 THEN             INSERT INTO #TEMPOUTPUTRESULT SELECT * FROM :MULTIPLEFORECAST_RESULT0 WHERE GROUPID=:GROUPID AND TIMESTAMP>:GROUPCNT;             INSERT INTO #TEMPOUTPARAMETER SELECT * FROM :MULTIPLEFORECAST_OUTPARAMETER0 WHERE GROUPID=:GROUPID;         ELSE              INSERT INTO #TEMPOUTPUTRESULT SELECT * FROM :MULTIPLEFORECAST_RESULT1 WHERE GROUPID=:GROUPID AND TIMESTAMP>:GROUPCNT;             INSERT INTO #TEMPOUTPARAMETER SELECT * FROM :MULTIPLEFORECAST_OUTPARAMETER1 WHERE GROUPID=:GROUPID;         END IF;     END FOR;          FOR ROWINDEX IN 0 .. :ROWCNT-1 DO         SELECT "GROUPID" INTO GROUPID FROM #TEMPGROUPID LIMIT 1 OFFSET :ROWINDEX;          SELECT MAX("TIMESTAMP") INTO GROUPCNT FROM :DATA_TABLE WHERE GROUPID=:GROUPID;         SELECT COUNT(*) INTO NEGATIVE_VALUE_CNT FROM #TEMPOUTPUTRESULT WHERE GROUPID=:GROUPID AND VALUE<0;         SELECT "MAXVALUE" INTO MAX_GROUP_VALUE FROM #TEMPGROUPID WHERE GROUPID=:GROUPID;         SELECT MAX("VALUE") INTO MAX_GROUP_FORECAST_VALUE FROM #TEMPOUTPUTRESULT WHERE GROUPID=:GROUPID;         SELECT "VALUE" INTO FORECAST_MODEL_NAME FROM #TEMPOUTPARAMETER WHERE GROUPID=:GROUPID AND NAME='FORECAST_MODEL_NAME';         IF (NEGATIVE_VALUE_CNT > GROUPCNT/2) OR (MAX_GROUP_FORECAST_VALUE > MAX_GROUP_VALUE*2) OR FORECAST_MODEL_NAME='SESM' OR FORECAST_MODEL_NAME='DESM' THEN             TEMP_MULTIPLEFORECAST_RESULT=SELECT * FROM #TEMPOUTPUTRESULT WHERE GROUPID<>:GROUPID;             TEMP_MULTIPLEFORECAST_OUTPARAMETER=SELECT * FROM #TEMPOUTPARAMETER WHERE GROUPID<>:GROUPID;             TRUNCATE TABLE #TEMPOUTPUTRESULT;             TRUNCATE TABLE #TEMPOUTPARAMETER;             INSERT INTO #TEMPOUTPUTRESULT SELECT * FROM :TEMP_MULTIPLEFORECAST_RESULT;             INSERT INTO #TEMPOUTPARAMETER SELECT * FROM :TEMP_MULTIPLEFORECAST_OUTPARAMETER;                          SELECT "INTARGS" INTO LR_FORECAST_NUMBER FROM :MULTIPLEFORECAST_CONTROLTBL WHERE GROUPID=:GROUPID AND NAME='FORECAST_NUM';             TRUNCATE TABLE #TEMPPALFORECASTSLRCONTROL;             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('FORECAST_LENGTH', :LR_FORECAST_NUMBER ,null,null);             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('TREND', null,0.9,null);             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('AFFECT_FUTURE_ONLY', 1,null,null);             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('SEASONALITY', 1,null,null);             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('PERIODS', 12,null,null);             INSERT INTO #TEMPPALFORECASTSLRCONTROL VALUES ('MEASURE_NAME', null, null, 'MSE');                          LR_DATA_TABLE=SELECT "TIMESTAMP", "VALUE" AS Y FROM :DATA_TABLE WHERE GROUPID=:GROUPID;             FORECASTSLR_CONTROL=SELECT * FROM #TEMPPALFORECASTSLRCONTROL;             CALL PALLRWITHSEASONALADJUST_PROC(:LR_DATA_TABLE, :FORECASTSLR_CONTROL, :FORECASTSLR_OUTPARAMETER, :FORECASTSLR_RESULT) ;              INSERT INTO #TEMPOUTPUTRESULT ("GROUPID", "TIMESTAMP", "VALUE") SELECT :GROUPID AS GROUPID, "TIMESTAMP", "VALUE" FROM :FORECASTSLR_RESULT WHERE TIMESTAMP>:GROUPCNT;             INSERT INTO #TEMPOUTPARAMETER ("GROUPID", "NAME", "VALUE") SELECT :GROUPID AS GROUPID, "NAME", "VALUE" FROM :FORECASTSLR_OUTPARAMETER;         END IF;     END FOR;      RESULT=SELECT "GROUPID", "TIMESTAMP",CASE WHEN "VALUE"<0 THEN 0 ELSE "VALUE" END AS "VALUE" FROM #TEMPOUTPUTRESULT;     SELECT * FROM #TEMPOUTPARAMETER; END
